for source, wanted in expected.items():
    oracle = canonical(source)
    actual = generated(source)
    print(
        f"input={source!r} canonical={oracle!r} generated={actual!r} "
        f"claimed={wanted!r}"
    )
    if oracle != wanted or actual != wanted:
        raise SystemExit(1)

